import 'package:flutter/material.dart' hide Icon;
import 'package:intl/intl.dart';
import 'modern_icons.dart';
import 'database_helper.dart';
import 'diary_entry.dart';
import 'work_page.dart';

class HistoryPage extends StatefulWidget {
  final String initialFilter;
  const HistoryPage({super.key, this.initialFilter = 'All'});
  @override State<HistoryPage> createState() => _HistoryPageState();
}
class _HistoryPageState extends State<HistoryPage> {
  late Future<List<DiaryEntry>> entriesFuture;
  final searchController = TextEditingController();
  String searchText = '';
  late String selectedFilter;
  @override void initState() { super.initState(); selectedFilter = widget.initialFilter; refreshEntries(); }
  void refreshEntries() { entriesFuture = DatabaseHelper.instance.getAllEntries(); }
  DateTime? _parseDate(String v) { final p = v.split('-'); if (p.length != 3) return null; return DateTime.tryParse('${p[2]}-${p[1]}-${p[0]}'); }
  DateTime _startOfWeek(DateTime d) { final x = DateTime(d.year, d.month, d.day); return x.subtract(Duration(days: x.weekday - 1)); }
  DateTime _endOfWeek(DateTime d) => _startOfWeek(d).add(const Duration(days: 6));
  String _dateLabel(DateTime d) => DateFormat('d MMM').format(d);
  String _weekLabel(DateTime d) => '${_dateLabel(d)}–${_dateLabel(_endOfWeek(d))}';
  String _monthLabel(DateTime d) => DateFormat('MMMM yyyy').format(d);
  List<DateTime> _weeksForLastFourMonths() { final n = DateTime.now(); final c = DateTime(n.year, n.month - 3, 1); var x = _startOfWeek(n); final r = <DateTime>[]; while (!x.isBefore(c)) { r.add(x); x = x.subtract(const Duration(days: 7)); } return r; }
  List<DateTime> _recentMonths(int c) { final n = DateTime.now(); return List.generate(c, (i) => DateTime(n.year, n.month - i, 1)); }

  Future<void> _showWeeklyHistory() async { final weeks = _weeksForLastFourMonths(); await showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true, builder: (sc) { final s = Theme.of(sc).colorScheme; return SafeArea(child: SizedBox(height: MediaQuery.of(sc).size.height * .78, child: Column(children: [Padding(padding: const EdgeInsets.fromLTRB(20, 4, 20, 12), child: Text('Weekly History', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800, color: s.onSurface))), Expanded(child: ListView.builder(itemCount: weeks.length, itemBuilder: (c, i) { final w = weeks[i]; return ListTile(leading: icon3D(context, Icons.calendar_view_week, size: 20), title: Text(i == 0 ? 'This Week' : '$i Week', style: TextStyle(fontWeight: FontWeight.w700, color: s.onSurface)), subtitle: Text(_weekLabel(w), style: TextStyle(color: s.onSurfaceVariant)), trailing: icon3D(context, Icons.chevron_right, size: 20), onTap: () { Navigator.pop(sc); setState(() => selectedFilter = 'Week:${w.toIso8601String()}'); }); })), ]))); }); }
  Future<void> _showMonthlyHistory() async { final months = _recentMonths(12); await showModalBottomSheet<void>(context: context, isScrollControlled: true, showDragHandle: true, builder: (sc) { final s = Theme.of(sc).colorScheme; return SafeArea(child: SizedBox(height: MediaQuery.of(sc).size.height * .78, child: Column(children: [Padding(padding: const EdgeInsets.fromLTRB(20, 4, 20, 12), child: Text('Monthly History', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w800, color: s.onSurface))), Expanded(child: ListView.builder(itemCount: months.length, itemBuilder: (c, i) { final m = months[i]; return ListTile(leading: icon3D(context, Icons.calendar_month, size: 20), title: Text(i == 0 ? 'This Month' : '$i Month', style: TextStyle(fontWeight: FontWeight.w700, color: s.onSurface)), subtitle: Text(_monthLabel(m), style: TextStyle(color: s.onSurfaceVariant)), trailing: icon3D(context, Icons.chevron_right, size: 20), onTap: () { Navigator.pop(sc); setState(() => selectedFilter = 'Month:${m.year}-${m.month.toString().padLeft(2, '0')}'); }); })), ]))); }); }
  Future<void> _searchByMonth() async { final n = DateTime.now(); final p = await showDatePicker(context: context, initialDate: n, firstDate: DateTime(2000), lastDate: DateTime(n.year + 1, 12, 31), helpText: 'Select any date in the month', fieldLabelText: 'Month'); if (p == null || !mounted) return; setState(() => selectedFilter = 'Month:${p.year}-${p.month.toString().padLeft(2, '0')}'); }
  Future<void> deleteEntry(int id) async { await DatabaseHelper.instance.deleteEntry(id); setState(refreshEntries); if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Entry Deleted Successfully'))); }
  Future<void> confirmDelete(DiaryEntry entry) async { final confirm = await showDialog<bool>(context: context, builder: (c) => AlertDialog(title: const Text('Delete Entry'), content: Text('Delete "${entry.itemName}" ?'), actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Cancel')), TextButton(onPressed: () => Navigator.pop(c, true), child: const Text('Delete'))])); if (confirm == true) await deleteEntry(entry.id!); }
  Widget icon3D(BuildContext context, IconData icon, {double size = 26, Color? color}) => Icon(icon, size: size);
  Widget themedCard({required Widget child, EdgeInsetsGeometry margin = const EdgeInsets.all(8), EdgeInsetsGeometry padding = const EdgeInsets.all(12)}) { final s = Theme.of(context).colorScheme; return Card(margin: margin, elevation: 2, color: s.surfaceContainerHighest, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16), side: BorderSide(color: s.primary.withValues(alpha: .12))), shadowColor: s.primary.withValues(alpha: .10), child: Padding(padding: padding, child: child)); }
  @override Widget build(BuildContext context) {
    final s = Theme.of(context).colorScheme;
    return Scaffold(backgroundColor: s.surface, appBar: AppBar(title: const Text('History'), backgroundColor: s.surface, elevation: 0), body: FutureBuilder<List<DiaryEntry>>(future: entriesFuture, builder: (context, snapshot) {
      if (snapshot.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator());
      if (snapshot.hasError) return Center(child: Text('Error: ${snapshot.error}'));
      final entries = snapshot.data ?? [];
      final filtered = entries.where((entry) { final q = searchText.toLowerCase(); if (!entry.itemName.toLowerCase().contains(q) && !entry.workDate.toLowerCase().contains(q)) return false; final d = _parseDate(entry.workDate); if (d == null) return false; final x = DateTime(d.year, d.month, d.day); if (selectedFilter == 'Today') { final n = DateTime.now(); return x == DateTime(n.year, n.month, n.day); } if (selectedFilter.startsWith('Week:')) { final w = DateTime.tryParse(selectedFilter.substring(5)); if (w == null) return false; return !x.isBefore(_startOfWeek(w)) && !x.isAfter(_endOfWeek(w)); } if (selectedFilter.startsWith('Month:')) { final p = selectedFilter.substring(6).split('-'); final y = int.tryParse(p[0]); final m = int.tryParse(p[1]); return y != null && m != null && d.year == y && d.month == m; } return true; }).toList();
      final totalPieces = filtered.fold<int>(0, (sum, e) => sum + e.pieces); final totalEarnings = filtered.fold<double>(0, (sum, e) => sum + e.total);
      return Column(children: [Padding(padding: const EdgeInsets.all(8), child: TextField(controller: searchController, style: TextStyle(color: s.onSurface), decoration: InputDecoration(hintText: 'Search Item or Date...', hintStyle: TextStyle(color: s.onSurfaceVariant), prefixIcon: icon3D(context, Icons.search, size: 22), filled: true, fillColor: s.surfaceContainerHighest, border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide(color: s.primary.withValues(alpha: .14))), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide(color: s.primary.withValues(alpha: .14)))), onChanged: (v) => setState(() => searchText = v))), Padding(padding: const EdgeInsets.fromLTRB(8, 8, 8, 0), child: Row(children: [Expanded(child: OutlinedButton.icon(onPressed: _showWeeklyHistory, icon: icon3D(context, Icons.calendar_view_week, size: 18), label: const Text('Weekly History'))), const SizedBox(width: 8), Expanded(child: OutlinedButton.icon(onPressed: _showMonthlyHistory, icon: icon3D(context, Icons.calendar_month, size: 18), label: const Text('Monthly History')))])), if (selectedFilter.startsWith('Week:') || selectedFilter.startsWith('Month:')) Padding(padding: const EdgeInsets.fromLTRB(12, 8, 12, 0), child: Row(children: [Expanded(child: Text(selectedFilter.startsWith('Week:') ? 'Selected Week: ${_weekLabel(DateTime.parse(selectedFilter.substring(5)))}' : 'Selected Month: ${_monthLabel(DateTime.parse('${selectedFilter.substring(6)}-01'))}', style: TextStyle(fontWeight: FontWeight.w700, color: s.onSurface))), TextButton(onPressed: () => setState(() => selectedFilter = 'All'), child: const Text('Clear'))])), const SizedBox(height: 8), themedCard(child: Row(mainAxisAlignment: MainAxisAlignment.spaceAround, children: [Column(children: [icon3D(context, Icons.list_alt_rounded, size: 22), const SizedBox(height: 2), Text('Entries', style: TextStyle(fontWeight: FontWeight.bold, color: s.onSurfaceVariant)), Text(filtered.length.toString(), style: TextStyle(color: s.onSurface, fontWeight: FontWeight.w800))]), Column(children: [icon3D(context, Icons.numbers, size: 22), const SizedBox(height: 2), Text('Pieces', style: TextStyle(fontWeight: FontWeight.bold, color: s.onSurfaceVariant)), Text(totalPieces.toString(), style: TextStyle(color: s.onSurface, fontWeight: FontWeight.w800))]), Column(children: [icon3D(context, Icons.payments, size: 22), const SizedBox(height: 2), Text('Earnings', style: TextStyle(fontWeight: FontWeight.bold, color: s.onSurfaceVariant)), Text('Rs ${totalEarnings.toStringAsFixed(0)}', style: TextStyle(color: s.onSurface, fontWeight: FontWeight.w800))])])), const SizedBox(height: 8), Expanded(child: filtered.isEmpty ? Center(child: Text('No Entries Yet', style: TextStyle(color: s.onSurfaceVariant))) : ListView.builder(itemCount: filtered.length, itemBuilder: (context, index) { final entry = filtered[index]; final date = _parseDate(entry.workDate); final dayName = date == null ? '' : DateFormat('EEEE').format(date); return themedCard(margin: const EdgeInsets.symmetric(horizontal: 8, vertical: 6), padding: const EdgeInsets.all(8), child: ListTile(contentPadding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2), title: Text(entry.itemName, style: TextStyle(fontWeight: FontWeight.bold, color: s.onSurface)), subtitle: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Item: ${entry.itemName}', style: TextStyle(color: s.onSurfaceVariant)), if (entry.sizes.trim().isNotEmpty) Text('Size: ${entry.sizes}', style: TextStyle(color: s.onSurfaceVariant)), Text('Pieces: ${entry.pieces}', style: TextStyle(color: s.onSurfaceVariant)), Text('$dayName, ${entry.workDate}', style: TextStyle(color: s.onSurfaceVariant))]), trailing: SizedBox(width: 132, child: Row(mainAxisAlignment: MainAxisAlignment.end, children: [Flexible(child: Text('Rs ${entry.total.toStringAsFixed(0)}', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 17, color: s.tertiary), overflow: TextOverflow.ellipsis)), const SizedBox(width: 2), IconButton(padding: EdgeInsets.zero, constraints: const BoxConstraints(minWidth: 36, minHeight: 36), tooltip: 'Edit', icon: icon3D(context, Icons.edit, size: 22), onPressed: () async { final r = await Navigator.push(context, MaterialPageRoute(builder: (_) => WorkPage(entry: entry))); if (r == true && mounted) setState(refreshEntries); }), IconButton(padding: EdgeInsets.zero, constraints: const BoxConstraints(minWidth: 36, minHeight: 36), tooltip: 'Delete', icon: icon3D(context, Icons.delete_forever, size: 23), onPressed: () => confirmDelete(entry))])))); }))];
    });
  }
  @override void dispose() { searchController.dispose(); super.dispose(); }
}
